   536  template <typename EntryData>
   537  struct StateTableDriver
   538  {
   539    inline StateTableDriver (const StateTable<EntryData> &machine_,
   540                             hb_buffer_t *buffer_,
   541                             hb_face_t *face_) :
   542                machine (machine_),
   543                buffer (buffer_),
   544                num_glyphs (face_->get_num_glyphs ()) {}
   545
   546    template <typename context_t>
   547    inline void drive (context_t *c)
   548    {
   549      hb_glyph_info_t *info = buffer->info;
   550
   551      if (!c->in_place)
   552        buffer->clear_output ();
   553
   554      unsigned int state = StateTable<EntryData>::STATE_START_OF_TEXT;
   555      bool last_was_dont_advance = false;
   556      for (buffer->idx = 0;;)
   557      {
   558        unsigned int klass = buffer->idx < buffer->len ?
   559                             machine.get_class (info[buffer->idx].codepoint, num_glyphs) :
   560                             (unsigned) StateTable<EntryData>::CLASS_END_OF_TEXT;
   561        const Entry<EntryData> *entry = machine.get_entryZ (state, klass);
   562        if (unlikely (!entry))
   563          break;
   564
   565        /* Unsafe-to-break before this if not in state 0, as things might
   566         * go differently if we start from state 0 here. */
   567        if (state && buffer->idx)
   568        {
   569          /* If there's no action and we're just epsilon-transitioning to state 0,
   570           * safe to break. */
   571          if (c->is_actionable (this, entry) ||
   572              !(entry->newState == StateTable<EntryData>::STATE_START_OF_TEXT &&
   573                entry->flags == context_t::DontAdvance))
   574            buffer->unsafe_to_break (buffer->idx - 1, buffer->idx + 1);
   575        }
   576
   577        /* Unsafe-to-break if end-of-text would kick in here. */
   578        if (buffer->idx + 2 <= buffer->len)
   579        {
   580          const Entry<EntryData> *end_entry = machine.get_entryZ (state, 0);
   581          if (c->is_actionable (this, end_entry))
   582            buffer->unsafe_to_break (buffer->idx, buffer->idx + 2);
   583        }
   584
   585        if (unlikely (!c->transition (this, entry)))
   586          break;
   587
   588        if (unlikely (!buffer->successful)) return;
   589
   590        last_was_dont_advance = (entry->flags & context_t::DontAdvance) && buffer->max_ops-- > 0;
