   522  struct InsertionSubtable
   523  {
   524    struct EntryData
   525    {
   526      HBUINT16    currentInsertIndex;     /* Zero-based index into the insertion glyph table.
   527                                           * The number of glyphs to be inserted is contained
   528                                           * in the currentInsertCount field in the flags.
   529                                           * A value of 0xFFFF indicates no insertion is to
   530                                           * be done. */
   531      HBUINT16    markedInsertIndex;      /* Zero-based index into the insertion glyph table.
   532                                           * The number of glyphs to be inserted is contained
   533                                           * in the markedInsertCount field in the flags.
   534                                           * A value of 0xFFFF indicates no insertion is to
   535                                           * be done. */
   536      public:
   537      DEFINE_SIZE_STATIC (4);
   538    };
   539
   540    struct driver_context_t
   541    {
   542      static const bool in_place = false;
   543      enum Flags
   544      {
   545        SetMark           = 0x8000,       /* If set, mark the current glyph. */
   546        DontAdvance       = 0x4000,       /* If set, don't advance to the next glyph before
   547                                           * going to the new state.  This does not mean
   548                                           * that the glyph pointed to is the same one as
   549                                           * before. If you've made insertions immediately
   550                                           * downstream of the current glyph, the next glyph
   551                                           * processed would in fact be the first one
   552                                           * inserted. */
   553        CurrentIsKashidaLike= 0x2000,     /* If set, and the currentInsertList is nonzero,
   554                                           * then the specified glyph list will be inserted
   555                                           * as a kashida-like insertion, either before or
   556                                           * after the current glyph (depending on the state
   557                                           * of the currentInsertBefore flag). If clear, and
   558                                           * the currentInsertList is nonzero, then the
   559                                           * specified glyph list will be inserted as a
   560                                           * split-vowel-like insertion, either before or
   561                                           * after the current glyph (depending on the state
   562                                           * of the currentInsertBefore flag). */
   563        MarkedIsKashidaLike= 0x1000,      /* If set, and the markedInsertList is nonzero,
   564                                           * then the specified glyph list will be inserted
   565                                           * as a kashida-like insertion, either before or
   566                                           * after the marked glyph (depending on the state
   567                                           * of the markedInsertBefore flag). If clear, and
   568                                           * the markedInsertList is nonzero, then the
   569                                           * specified glyph list will be inserted as a
   570                                           * split-vowel-like insertion, either before or
   571                                           * after the marked glyph (depending on the state
   572                                           * of the markedInsertBefore flag). */
   573        CurrentInsertBefore= 0x0800,      /* If set, specifies that insertions are to be made
   574                                           * to the left of the current glyph. If clear,
   575                                           * they're made to the right of the current glyph. */
   576        MarkedInsertBefore= 0x0400,       /* If set, specifies that insertions are to be
   577                                           * made to the left of the marked glyph. If clear,
   578                                           * they're made to the right of the marked glyph. */
   579        CurrentInsertCount= 0x3E0,        /* This 5-bit field is treated as a count of the
   580                                           * number of glyphs to insert at the current
   581                                           * position. Since zero means no insertions, the
   582                                           * largest number of insertions at any given
   583                                           * current location is 31 glyphs. */
   584        MarkedInsertCount= 0x001F,        /* This 5-bit field is treated as a count of the
   585                                           * number of glyphs to insert at the marked
   586                                           * position. Since zero means no insertions, the
   587                                           * largest number of insertions at any given
   588                                           * marked location is 31 glyphs. */
   589      };
   590
   591      inline driver_context_t (const InsertionSubtable *table,
   592                               hb_aat_apply_context_t *c_) :
   593          ret (false),
   594          c (c_),
   595          mark_set (false),
   596          mark (0),
   597          insertionAction (table+table->insertionAction) {}
   598
   599      inline bool is_actionable (StateTableDriver<EntryData> *driver,
   600                                 const Entry<EntryData> *entry)
   601      {
   602        return (entry->flags & (CurrentInsertCount | MarkedInsertCount)) &&
   603               (entry->data.currentInsertIndex != 0xFFFF ||entry->data.markedInsertIndex != 0xFFFF);
   604      }
   605      inline bool transition (StateTableDriver<EntryData> *driver,
   606                              const Entry<EntryData> *entry)
   607      {
   608        hb_buffer_t *buffer = driver->buffer;
   609        unsigned int flags = entry->flags;
   610
   611        if (entry->data.markedInsertIndex != 0xFFFF && mark_set)
   612        {
   613          unsigned int count = (flags & MarkedInsertCount);
   614          unsigned int start = entry->data.markedInsertIndex;
   615          const GlyphID *glyphs = &insertionAction[start];
   616          if (unlikely (!c->sanitizer.check_array (glyphs, count))) return false;
   617
   618          bool before = flags & MarkedInsertBefore;
   619
   620          unsigned int end = buffer->out_len;
   621          buffer->move_to (mark);
   622
   623          if (!before)
   624            buffer->copy_glyph ();
   625          /* TODO We ignore KashidaLike setting. */
   626          for (unsigned int i = 0; i < count; i++)
   627            buffer->output_glyph (glyphs[i]);
   628          if (!before)
   629            buffer->skip_glyph ();
   630
   631          buffer->move_to (end + count);
   632
   633          buffer->unsafe_to_break_from_outbuffer (mark, MIN (buffer->idx + 1, buffer->len));
   634        }
   635
   636        if (entry->data.currentInsertIndex != 0xFFFF)
   637        {
   638          unsigned int count = (flags & CurrentInsertCount) >> 5;
   639          unsigned int start = entry->data.currentInsertIndex;
   640          const GlyphID *glyphs = &insertionAction[start];
   641          if (unlikely (!c->sanitizer.check_array (glyphs, count))) return false;
   642
   643          bool before = flags & CurrentInsertBefore;
   644
   645          unsigned int end = buffer->out_len;
   646
   647          if (!before)
   648            buffer->copy_glyph ();
   649          /* TODO We ignore KashidaLike setting. */
   650          for (unsigned int i = 0; i < count; i++)
   651            buffer->output_glyph (glyphs[i]);
   652          if (!before)
   653            buffer->skip_glyph ();
   654
   655          /* Humm. Not sure where to move to.  There's this wording under
   656           * DontAdvance flag:
   657           *
   658           * "If set, don't update the glyph index before going to the new state.
   659           * This does not mean that the glyph pointed to is the same one as
   660           * before. If you've made insertions immediately downstream of the
   661           * current glyph, the next glyph processed would in fact be the first
   662           * one inserted."
   663           *
   664           * This suggests that if DontAdvance is NOT set, we should move to
   665           * end+count.  If it *was*, then move to end, such that newly inserted
   666           * glyphs are now visible.
   667           */
   668          buffer->move_to ((flags & DontAdvance) ? end : end + count);
   669        }
   670
   671        if (flags & SetMark)
   672        {
   673          mark_set = true;
   674          mark = buffer->out_len;
   675        }
   676
   677        return true;
   678      }
   679
   680      public:
   681      bool ret;
   682      private:
   683      hb_aat_apply_context_t *c;
   684      bool mark_set;
   685      unsigned int mark;
   686      const UnsizedArrayOf<GlyphID> &insertionAction;
   687    };
