   815  struct Chain
   816  {
   817    inline void apply (hb_aat_apply_context_t *c) const
   818    {
   819      uint32_t flags = defaultFlags;
   820      {
   821        /* Compute applicable flags.  TODO Should move this to planning
   822         * stage and take user-requested features into account. */
   823        unsigned int count = featureCount;
   824        for (unsigned i = 0; i < count; i++)
   825        {
   826          const Feature &feature = featureZ[i];
   827          if (false) /* XXX Check if feature enabled... */
   828          {
   829            flags &= feature.disableFlags;
   830            flags |= feature.enableFlags;
   831          }
   832        }
   833      }
   834
