   987                                   * 2 or 3. */
   988    HBUINT16      unused;         /* Set to 0. */
   989    HBUINT32      chainCount;     /* Number of metamorphosis chains contained in this
   990                                   * table. */
   991    Chain         firstChain;     /* Chains. */
   992
   993    public:
   994    DEFINE_SIZE_MIN (8);
